('r11', 'retail', 'medium', 'Rate', 'What percentage of order lines were returned?', "SELECT ROUND(100.0 * SUM(CASE WHEN returned = 'Yes' THEN 1 ELSE 0 END) / COUNT(*), 2) AS return_rate_pct FROM data"),
('r12', 'retail', 'medium', 'Top N + filter', 'Which store has the highest revenue in the North region?', "SELECT store FROM data WHERE region = 'North' GROUP BY store ORDER BY SUM(revenue) DESC LIMIT 1"),
