('r14', 'retail', 'medium', 'Date range', 'What was our total profit in Q1 2025?', "SELECT ROUND(SUM(revenue) - SUM(cost), 2) AS profit FROM data WHERE order_date BETWEEN '2025-01-01' AND '2025-03-31'"),
('r15', 'retail', 'hard', 'Period comparison', 'By what percentage did revenue change between the first half of 2024 and the first half of 2025?', "SELECT ROUND(100.0 * (SUM(CASE WHEN order_date BETWEEN '2025-01-01' AND '2025-06-30' THEN revenue ELSE 0 END) - SUM(CASE WHEN order_date BETWEEN '2024-01-01' AND '2024-06-30' THEN revenue ELSE 0 END)) / SUM(CASE WHEN order_date BETWEEN '2024-01-01' AND '2024-06-30' THEN revenue ELSE 0 END), 2) AS change_pct FROM data"),
('r16', 'retail', 'hard', 'Rate + threshold', 'Among products with at least 60 order lines, which has the highest return rate?', "SELECT product FROM data GROUP BY product HAVING COUNT(*) >= 60 ORDER BY 1.0 * SUM(CASE WHEN returned = 'Yes' THEN 1 ELSE 0 END) / COUNT(*) DESC LIMIT 1"),
